CREATE TABLE IF NOT EXISTS connector_events (id INTEGER PRIMARY KEY AUTOINCREMENT,connector_id INTEGER,event TEXT NOT NULL,status TEXT NOT NULL,details TEXT DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,connector_id INTEGER,source_url TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',message TEXT DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recommendations (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,novel_id INTEGER,reason TEXT,score REAL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_connector_events_connector ON connector_events(connector_id,created_at);
CREATE INDEX IF NOT EXISTS idx_import_jobs_user ON import_jobs(user_id,created_at);
